def regions(grid,bg):
    h,w=len(grid),len(grid[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j]!=bg and (i,j) not in seen: continue
            if (i,j) in seen: continue
            comp=[]; st=[(i,j)]; seen.add((i,j))
            while st:
                y,x=st.pop(); comp.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and grid[ny][nx]==bg and (ny,nx) not in seen:
                        seen.add((ny,nx)); st.append((ny,nx))
            # enclosed if doesn't touch border
            if not any(y in(0,h-1) or x in(0,w-1) for y,x in comp): out.append(comp)
    return out
