def reach(grid,bg):
    h,w=len(grid),len(grid[0]); seen=set(); st=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j]==bg and (i in(0,h-1) or j in(0,w-1)):
                st.append((i,j)); seen.add((i,j))
    while st:
        y,x=st.pop()
        for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
            ny,nx=y+dy,x+dx
            if 0<=ny<h and 0<=nx<w and grid[ny][nx]==bg and (ny,nx) not in seen:
                seen.add((ny,nx)); st.append((ny,nx))
    return seen
