def transform(grid):
    from collections import Counter
    import copy
    c=Counter(x for r in grid for x in r)
    bg=c.most_common(1)[0][0]
    h,w=len(grid),len(grid[0])
    r=reach(grid,bg)
    pockets={}
    for y in range(h):
        for x in range(w):
            if grid[y][x]==bg and (y,x) not in r:
                pockets.setdefault(id,None)
    # group pockets into components
    seen=set(); g=copy.deepcopy(grid)
    for y in range(h):
        for x in range(w):
            if (y,x) in pockets and (y,x) not in seen:
                st=[(y,x)]; seen.add((y,x)); comp=[]
                while st:
                    cy,cx=st.pop(); comp.append((cy,cx))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=cy+dy,cx+dx
                        if 0<=ny<h and 0<=nx<w and (ny,nx) in pockets and (ny,nx) not in seen:
                            seen.add((ny,nx)); st.append((ny,nx))
                ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                y0,y1,x0,x1=min(ys),max(ys),min(xs),max(xs)
                ring=all(0<=yy<h and 0<=xx<w and grid[yy][xx]!=bg
                         for yy in range(y0-1,y1+2) for xx in range(x0-1,x1+2)
                         if not (y0<=yy<=y1 and x0<=xx<=x1))
                if ring:
                    for cy,cx in comp: g[cy][cx]=4
    return g
